## 커스텀 프로퍼티 위임 구현

### 실무 예제: TTL 캐싱 위임

```kotlin
class CachedProperty<T>(
    private val ttlMillis: Long,
    private val loader: () -> T
) : ReadOnlyProperty<Any?, T> {

    private var cachedValue: T? = null
    private var lastLoadTime: Long = 0

    override fun getValue(thisRef: Any?, property: KProperty<*>): T {
        val now = System.currentTimeMillis()
        if (cachedValue == null || now - lastLoadTime > ttlMillis) {
            cachedValue = loader()
            lastLoadTime = now
        }
        return cachedValue!!
    }
}

// 편의 함수
fun <T> cached(ttlMillis: Long, loader: () -> T) = CachedProperty(ttlMillis, loader)

// 사용
class FeatureFlagService(private val client: ConfigClient) {
    // 5분마다 갱신
    val flags: Map<String, Boolean> by cached(ttlMillis = 300_000) {
        client.loadFeatureFlags()
    }
}
```

### 실무 예제: Spring Environment 위임

```kotlin
class SpringEnvDelegate<T>(
    private val env: Environment,
    private val key: String,
    private val type: Class<T>,
    private val default: T? = null
) : ReadOnlyProperty<Any?, T> {

    override fun getValue(thisRef: Any?, property: KProperty<*>): T {
        return env.getProperty(key, type)
            ?: default
            ?: throw IllegalStateException("Property '$key' not found")
    }
}

// 편의 확장 함수
inline fun <reified T> Environment.delegate(
    key: String,
    default: T? = null
) = SpringEnvDelegate(this, key, T::class.java, default)

// 사용
@Service
class OrderService(env: Environment) {
    val maxOrderItems: Int by env.delegate("order.max-items", default = 100)
    val orderTimeout: String by env.delegate("order.timeout")
}
```

### 실무 예제: 감사 로깅 위임

```kotlin
class AuditableDelegate<T>(
    initialValue: T,
    private val fieldName: String,
    private val auditLogger: AuditLogger
) : ReadWriteProperty<Any?, T> {

    private var value = initialValue

    override fun getValue(thisRef: Any?, property: KProperty<*>): T = value

    override fun setValue(thisRef: Any?, property: KProperty<*>, newValue: T) {
        val oldValue = value
        value = newValue
        auditLogger.log(fieldName, oldValue, newValue)
    }
}
```

