    override fun getValue(thisRef: Any?, property: KProperty<*>): Boolean {
        if (cachedValue == null || Duration.between(lastCheck, Instant.now()) > Duration.ofMinutes(1)) {
            cachedValue = flagService.isEnabled(flagName)
            lastCheck = Instant.now()
        }
        return cachedValue!!
    }
}

@Service
class PaymentService(flagService: FeatureFlagService) {
    val isNewPaymentFlow: Boolean by FeatureFlagDelegate(flagService, "new-payment-flow")

    fun processPayment(order: Order) {
        if (isNewPaymentFlow) {
            // 새로운 결제 플로우
        } else {
            // 기존 결제 플로우
        }
    }
}
```

### 설정 변경 감지 + 리로드

```kotlin
@Component
class DynamicConfigHolder(
    @Value("\${app.rate-limit}") initialRateLimit: Int
) {
    var rateLimit: Int by Delegates.observable(initialRateLimit) { _, old, new ->
        if (old != new) {
            logger.info("Rate limit changed: $old → $new")
            rateLimiter.updateLimit(new)
        }
    }

    // Spring Cloud Config 변경 시 호출
    @EventListener(RefreshScopeRefreshedEvent::class)
