suspend fun enrichOrder(order: Order): EnrichedOrder = supervisorScope {
    // 3개의 외부 API를 병렬 호출
    val userDeferred = async {
        runCatching { userClient.getUser(order.userId) }
    }
    val productDeferred = async {
