### Item 3, 5, 7: 방어적 프로그래밍 삼총사

```kotlin
// require: 인자 검증 → IllegalArgumentException
fun setAge(age: Int) {
    require(age in 0..150) { "나이 범위 초과: $age" }
}

// check: 상태 검증 → IllegalStateException
fun processPayment() {
    check(status == OrderStatus.CONFIRMED) {
        "결제는 확인된 주문만 가능합니다. 현재 상태: $status"
    }
}

// assert: 개발 시 불변 조건 확인 (프로덕션에서 비활성화 가능)
fun calculate(items: List<Item>): Money {
    val total = items.sumOf { it.price.amountInCents }
    assert(total >= 0) { "총액이 음수: $total" }
    return Money(total)
}
```

